// 7x7 grid, rows indexed from bottom: 1..7; columns left to right: 1..7
unitsize(18);
import graph;

pen gridpen = gray(0.6)+linewidth(0.7);
pen redc = rgb(0.85,0.25,0.25);
pen bluec = rgb(0.25,0.45,0.85);

// fill a unit cell at column i, row j with color p
void fillcell(int i, int j, pen p) {
  fill(box((i-1,j-1),(i,j)), p);
}

// 1) rows 5,6,7 all red
for (int j=5; j<=7; ++j)
  for (int i=1; i<=7; ++i)
    fillcell(i,j,redc);

// 2) columns 5,6,7 blue in rows 1..4
for (int j=1; j<=4; ++j)
  for (int i=5; i<=7; ++i)
